import json, sys

def preview(s, n=220):
    if not isinstance(s, str):
        s = json.dumps(s)
    s = s.replace("\n", " ")
    return s[:n] + ("..." if len(s) > n else "")

def main(path):
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
            except Exception as e:
                print(f"[{i}] PARSE ERROR {e}")
                continue
            t = o.get("type")
            ts = o.get("timestamp", "")
            if t == "user" or t == "assistant":
                msg = o.get("message", {})
                role = msg.get("role", t)
                content = msg.get("content", "")
                if isinstance(content, list):
                    parts = []
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text":
                            parts.append(f"TEXT: {preview(c.get('text',''))}")
                        elif ctype == "tool_use":
                            parts.append(f"TOOL_USE[{c.get('name')}]: {preview(c.get('input',{}))}")
                        elif ctype == "tool_result":
                            cont = c.get("content","")
                            parts.append(f"TOOL_RESULT: {preview(cont)}")
                        else:
                            parts.append(f"{ctype}: {preview(c)}")
                    body = " | ".join(parts)
                else:
                    body = preview(content)
                print(f"[{i}] {ts} {role}: {body}")
            elif t == "attachment":
                hookName = o.get("attachment",{}).get("hookName","")
                content = o.get("attachment",{}).get("content","")
                print(f"[{i}] {ts} ATTACHMENT[{hookName}]: {preview(content)}")
            else:
                print(f"[{i}] {ts} {t}: {preview(o)}")

if __name__ == "__main__":
    main(sys.argv[1])
EOF
echo done

